string reverseWords(string s) {
    stringstream in(s);
    vector<string> words;
    string w;
    while (in >> w) words.push_back(w);          // >> skips any number of spaces
    reverse(words.begin(), words.end());
    string out;
    for (size_t i = 0; i < words.size(); i++) {
        if (i > 0) out += ' ';
        out += words[i];
    }
    return out;
}

function reverseWords(s) {
  const words = [];
  let i = s.length - 1;
  while (i >= 0) {
    while (i >= 0 && s[i] === " ") i--;      // skip spaces
    if (i < 0) break;
    const end = i;                            // the last letter of a word
    while (i >= 0 && s[i] !== " ") i--;      // walk back to the space before it
    words.push(s.slice(i + 1, end + 1));      // the word is s[i+1..end]
  }
  return words.join(" ");
}

def reverse_words(s):
    words = []
    i = len(s) - 1
    while i >= 0:
        while i >= 0 and s[i] == " ":
            i -= 1                        # skip spaces
        if i < 0:
            break
        end = i                           # the last letter of a word
        while i >= 0 and s[i] != " ":
