String reverseWords(String s) {
    StringBuilder out = new StringBuilder();
    int i = s.length() - 1;
    while (i >= 0) {
        while (i >= 0 && s.charAt(i) == ' ') i--;    // skip spaces
        if (i < 0) break;
        int end = i;                                 // the last letter of a word
        while (i >= 0 && s.charAt(i) != ' ') i--;    // walk back to the space before it
        if (out.length() > 0) out.append(' ');
        out.append(s, i + 1, end + 1);               // the word is s[i+1..end]
    }
    return out.toString();
}

string reverseWords(string s) {
    string out;
    int i = (int)s.size() - 1;
    while (i >= 0) {
        while (i >= 0 && s[i] == ' ') i--;           // skip spaces
        if (i < 0) break;
        int end = i;                                 // the last letter of a word
        while (i >= 0 && s[i] != ' ') i--;           // walk back to the space before it
        if (!out.empty()) out += ' ';
        out += s.substr(i + 1, end - i);             // the word is s[i+1..end]
    }
    return out;
}
